package cn.studypilot.assessment;
import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper; import cn.studypilot.assessment.model.*; import cn.studypilot.assessment.repository.AssessmentRepository; import cn.studypilot.assessment.service.AssessmentService; import cn.studypilot.model.dto.ModelResponse; import cn.studypilot.model.gateway.ModelGateway; import java.time.Duration; import java.util.List; import org.junit.jupiter.api.Test;
class AssessmentServiceTest {
 @Test void gradesObjectiveAndShortAnswersThenRecordsLearningEvidence(){var repo=mock(AssessmentRepository.class);var model=mock(ModelGateway.class);when(repo.findInProgressAttempt(5,9)).thenReturn(new AttemptContext(9,3,List.of(new AssessableItem(1,"SINGLE_CHOICE","A","进程",5),new AssessableItem(2,"SHORT_ANSWER","程序的一次执行。","进程",10))));when(model.complete(any())).thenReturn(new ModelResponse("test","{\"score\":8,\"feedback\":\"概念正确但不够完整。\"}",Duration.ZERO));var service=new AssessmentService(repo,model,new ObjectMapper());var report=service.submit(5,9,List.of(new SubmittedAnswer(1,"A"),new SubmittedAnswer(2,"一次执行的程序")));assertThat(report.totalScore()).isEqualTo(13);verify(repo,times(2)).saveGradedAnswer(eq(9L),any(),anyString());verify(repo,times(2)).updateMastery(eq(5L),eq("进程"),anyDouble());verify(repo).completeAttempt(9,13);}
 @Test void rejectsMissingOrRepeatedAnswers(){var repo=mock(AssessmentRepository.class);when(repo.findInProgressAttempt(5,9)).thenReturn(new AttemptContext(9,3,List.of(new AssessableItem(1,"SINGLE_CHOICE","A","进程",5))));var service=new AssessmentService(repo,mock(ModelGateway.class),new ObjectMapper());assertThatThrownBy(()->service.submit(5,9,List.of())).isInstanceOf(IllegalArgumentException.class);}
}
